import { Bleed, Box, Button, ErrorMessage, HStack, VStack } from '@navikt/ds-react';
import { useForm, useStore, type ValidationError } from '@tanstack/react-form';
import { useAtomValue, useSetAtom } from 'jotai';
import { useCallback, useMemo, useRef, useState } from 'react';
import { AvbrytAlert } from 'src/components/melding/AvbrytAlert';
import DraftStatus from 'src/components/melding/DraftStatus';
import nyMeldingSchema, { maksLengdeMelding } from 'src/components/melding/nyMeldingSchema';
import { Oppgaveliste } from 'src/components/melding/OppgavelisteOptions';
import { SaksbehandlerNavnDialog } from 'src/components/melding/SaksbehandlerNavnDialog';
import { SendOgJournalforModal } from 'src/components/melding/SendOgJournalforModal';
import AutoCompleteTekstTips from 'src/components/melding/standardtekster/AutoCompleteTekstTips';
import StandardTekstModal from 'src/components/melding/standardtekster/StandardTeksterModal';
import { settInnStandardTekst } from 'src/components/melding/standardtekster/settInnStandardTekst';
import { ValgForMeldingstype } from 'src/components/melding/ValgForMeldingstype';
import { MeldingsType, meldingsTyperTekst, VelgMeldingsType } from 'src/components/melding/VelgMeldingsType';
import VelgOppgaveliste from 'src/components/melding/VelgOppgaveliste';
import VelgTema from 'src/components/melding/VelgTema';
import VelgSak from 'src/components/sakVelger/VelgSak';
import {
    type JournalforingSak,
    type SendMeldingRequestV2,
    SendMeldingRequestV2TraadType
} from 'src/generated/modiapersonoversikt-api';
import { useSendMelding } from 'src/lib/clients/modiapersonoversikt-api';
import useDraft from 'src/lib/hooks/useDraft';
import { useSuspendingBrukernavn } from 'src/lib/hooks/useSuspendingBrukernavn';
import { aktivEnhetAtom, usePersonAtomValue } from 'src/lib/state/context';
import { nyMeldingUnderArbeidAtom, overskridKontaktReservasjonAtom, useDisableDialog } from 'src/lib/state/dialog';
import type { Draft, DraftContext } from 'src/models/meldinger/draft';
import type { Temagruppe } from 'src/models/temagrupper';
import { trackGenereltUmamiEvent, trackingEvents, trackSendNyMelding } from 'src/utils/analytics';
import useDynamicHeightTextArea from 'src/utils/hooks/use-dynamic-height-text-area';
import type { z } from 'zod';
import AutocompleteTextarea from './AutoCompleteTextarea';

const defaultSubmitMeta: { velgSak?: boolean; sak?: JournalforingSak } = {};

function NyMelding() {
    const fnr = usePersonAtomValue();
    const enhetsId = useAtomValue(aktivEnhetAtom);
    const brukerNavn = useSuspendingBrukernavn();
    const disableDialog = useDisableDialog();
    const setOverskridKontaktReservasjon = useSetAtom(overskridKontaktReservasjonAtom);
    const setNyMeldingUnderArbeid = useSetAtom(nyMeldingUnderArbeidAtom);
    const minRows = useDynamicHeightTextArea();

    const { mutate, isPending } = useSendMelding();
    const [visJournalforing, setVisJournalforing] = useState(false);
    const sender = useRef(false);

    // Brukes for å sette initialverdien til meldingen basert på draften
    const [defaultMessage, setDefaultMessage] = useState('');
    const draftLoader = useCallback((draft: Draft) => setDefaultMessage(draft.content), []);
    const draftContext: DraftContext = useMemo(() => ({ fnr }), [fnr]);

    const { update: updateDraft, remove: removeDraft, status: draftStatus } = useDraft(draftContext, draftLoader);

    const defaultFormOptions: DefaultFormOptions = {
        meldingsType: undefined,
        melding: defaultMessage,
        tema: undefined,
        oppgaveliste: Oppgaveliste.MinListe,
        sak: undefined,
        fnr: fnr ?? '',
        enhetsId: enhetsId ?? ''
    };
    const form = useForm({
        defaultValues: defaultFormOptions,
        validators: {
            onSubmit: nyMeldingSchema
        },
        onSubmitMeta: defaultSubmitMeta,
        onSubmit: ({ value, meta }) => {
            if (disableDialog || sender.current) return;
            if (meta.velgSak && value.meldingsType === MeldingsType.Referat) {
                setVisJournalforing(true);
                return;
            }
            const body = generateRequestBody(value as NyMeldingSchema);
            if (value.meldingsType === MeldingsType.Referat && meta.sak) {
                body.sak = { ...meta.sak, fnr: undefined };
            }
            if (meldingsType) trackSendNyMelding(meldingsTyperTekst[meldingsType].tittel.toLowerCase());
            sender.current = true;
            mutate(
                { body: body },
                {
                    onSuccess: () => {
                        removeDraft();
                        form.reset(
                            {
                                ...defaultFormOptions,
                                melding: '',
                                meldingsType
                            },
                            { keepDefaultValues: true }
                        );
                        setOverskridKontaktReservasjon(false);
                        setNyMeldingUnderArbeid(false);
                    },
                    onSettled: () => {
                        sender.current = false;
                    }
                }
            );
        }
    });

    const meldingsType = useStore(form.store, (state) => state.values.meldingsType);
    const meldingsTypeTekst = meldingsType ? meldingsTyperTekst[meldingsType] : undefined;
    const textAreaRef = useRef<HTMLTextAreaElement>(null);

    return (
        <>
            <form
                onSubmit={async (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    await form.handleSubmit();
                }}
            >
                <fieldset disabled={isPending} className="min-w-0" aria-label="Ny melding">
                    <VStack gap="space-16">
                        <form.Field name="meldingsType">
                            {(field) => (
                                <VelgMeldingsType
                                    error={
                                        field.state.meta.errors.length ? (
                                            <ValidationErrorMessage errors={field.state.meta.errors} />
                                        ) : undefined
                                    }
                                    meldingsType={field.state.value}
                                    setMeldingsType={(meldingsType) => {
                                        form.reset({
                                            ...defaultFormOptions,
                                            melding: form.getFieldValue('melding'),
                                            sak:
                                                meldingsType !== MeldingsType.Referat
                                                    ? form.getFieldValue('sak')
                                                    : undefined
                                        });
                                        field.handleChange(meldingsType);
                                    }}
                                />
                            )}
                        </form.Field>
                        <ValgForMeldingstype
                            meldingsType={meldingsType}
                            velgTema={
                                <form.Field name="tema">
                                    {(field) => (
                                        <VelgTema
                                            valgtTema={field.state.value}
                                            setValgtTema={(tema) => field.handleChange(tema)}
                                            error={
                                                field.state.meta.errors.length ? (
                                                    <ValidationErrorMessage errors={field.state.meta.errors} />
                                                ) : undefined
                                            }
                                        />
                                    )}
                                </form.Field>
                            }
                            velgOppgaveliste={
                                <form.Field name="oppgaveliste">
                                    {(field) => (
                                        <VelgOppgaveliste
                                            valgtOppgaveliste={field.state.value}
                                            setValgtOppgaveliste={(oppgaveliste) => field.handleChange(oppgaveliste)}
                                        />
                                    )}
                                </form.Field>
                            }
                            velgSak={
                                <form.Field name="sak">
                                    {(field) => (
                                        <VelgSak
                                            valgtSak={field.state.value}
                                            setSak={field.handleChange}
                                            error={<ValidationErrorMessage errors={field.state.meta.errors} />}
                                        />
                                    )}
                                </form.Field>
                            }
                        />
                        <VStack gap="space-4">
                            <form.Field
                                name="melding"
                                listeners={{
                                    onChange: ({ value }) => {
                                        if (value.length === 0) {
                                            removeDraft();
                                        }
                                        if (value.length > 0) {
                                            updateDraft(value);
                                        }
                                    }
                                }}
                            >
                                {(field) => (
                                    <div>
                                        <Box height="30px">
                                            {draftStatus &&
                                                form.getFieldValue('melding').length > 0 &&
                                                form.getFieldMeta('melding')?.isDirty && (
                                                    <DraftStatus state={draftStatus} />
                                                )}
                                        </Box>
                                        <AutocompleteTextarea
                                            disabled={disableDialog}
                                            ref={textAreaRef}
                                            label={meldingsTypeTekst?.tittel}
                                            hideLabel
                                            size="small"
                                            value={field.state.value}
                                            onChange={(e) => field.handleChange(e.target.value)}
                                            error={buildErrorMessage(field.state.meta.errors)}
                                            maxLength={maksLengdeMelding}
                                            resize="vertical"
                                            minRows={minRows}
                                            maxRows={50}
                                        />
                                    </div>
                                )}
                            </form.Field>
                            <Bleed
                                marginBlock={{
                                    xs: 'space-0 space-0',
                                    md: disableDialog ? 'space-0 space-0' : 'space-20 space-0'
                                }}
                                asChild
                            >
                                <HStack gap="space-4" justify="end">
                                    <Box height="15px" width="100px" />
                                    <HStack justify="end" wrap={false}>
                                        <AutoCompleteTekstTips />
                                        <StandardTekstModal
                                            textAreaRef={textAreaRef}
                                            submitTekst={(standardTekst) =>
                                                settInnStandardTekst(standardTekst, textAreaRef, (e) =>
                                                    form.setFieldValue('melding', e.target.value)
                                                )
                                            }
                                        />
                                        <SaksbehandlerNavnDialog />
                                    </HStack>
                                    <HStack
                                        justify="end"
                                        gap="space-8"
                                        align="center"
                                        flexGrow="1"
                                        maxWidth="fit-content"
                                        className="flex-row-reverse"
                                    >
                                        <Button
                                            disabled={disableDialog || isPending}
                                            type="submit"
                                            size="small"
                                            data-testid="svar-knapp"
                                            loading={isPending}
                                        >
                                            Send til {brukerNavn}
                                        </Button>
                                        {meldingsType === MeldingsType.Referat && (
                                            <Button
                                                type="button"
                                                variant="secondary"
                                                size="small"
                                                disabled={disableDialog || isPending}
                                                onClick={() => form.handleSubmit({ velgSak: true })}
                                            >
                                                Send og journalfør
                                            </Button>
                                        )}
                                        <AvbrytAlert
                                            disablePopup={form.getFieldValue('melding').length === 0}
                                            handleAvbryt={() => {
                                                removeDraft();
                                                setNyMeldingUnderArbeid(false);
                                                trackGenereltUmamiEvent(trackingEvents.avbrytMelding);
                                            }}
                                        />
                                    </HStack>
                                </HStack>
                            </Bleed>
                        </VStack>
                    </VStack>
                </fieldset>
            </form>
            {visJournalforing && (
                <SendOgJournalforModal
                    isPending={isPending}
                    disabled={disableDialog}
                    onClose={() => {
                        if (!sender.current) setVisJournalforing(false);
                    }}
                    onConfirm={(sak) => form.handleSubmit({ sak })}
                />
            )}
        </>
    );
}

function ValidationErrorMessage({ errors }: { errors: ValidationError[] }) {
    return errors.isNotEmpty() ? <ErrorMessage size="small">{buildErrorMessage(errors)}</ErrorMessage> : null;
}

function buildErrorMessage(errors: ValidationError[]) {
    const flatErrors = errors.flatMap((e) => (Array.isArray(e) ? e : [e]));
    return flatErrors.length > 0
        ? flatErrors
              .filter((e) => e.message != null)
              .map((e) => e.message)
              .join(', ')
        : null;
}

// Funksjonen forventer at parameteren allerede er validert
function generateRequestBody(value: NyMeldingSchema) {
    const common: Pick<SendMeldingRequestV2, 'enhet' | 'fritekst' | 'fnr'> = {
        enhet: value.enhetsId,
        fritekst: value.melding,
        fnr: value.fnr
    };
    let request: SendMeldingRequestV2 | undefined;

    switch (value.meldingsType) {
        case MeldingsType.Referat:
            request = {
                ...common,
                traadType: SendMeldingRequestV2TraadType.SAMTALEREFERAT,
                temagruppe: value.tema
            };
            break;
        case MeldingsType.Samtale:
            request = {
                ...common,
                traadType: SendMeldingRequestV2TraadType.MELDINGSKJEDE,
                avsluttet: false,
                erOppgaveTilknyttetAnsatt: value.oppgaveliste === Oppgaveliste.MinListe,
                sak: value.sak
            };
            break;
        case MeldingsType.Infomelding:
            request = {
                ...common,
                traadType: SendMeldingRequestV2TraadType.MELDINGSKJEDE,
                avsluttet: true,
                sak: value.sak,
                erOppgaveTilknyttetAnsatt: value.oppgaveliste === Oppgaveliste.MinListe
            };
            break;
        default:
            throw new Error(`Ukjent meldingsType: ${value.meldingsType}`);
    }
    return request;
}

type NyMeldingSchema = z.infer<typeof nyMeldingSchema>;

interface DefaultFormOptions {
    meldingsType?: MeldingsType;
    melding: string;
    tema?: Temagruppe;
    oppgaveliste?: Oppgaveliste;
    sak?: JournalforingSak;
    fnr: string;
    enhetsId: string;
}

export default NyMelding;
